:host([data-pos="left"]) .pill,:host([data-pos="right"]) .pill{transition:top .42s cubic-bezier(.32,.72,0,1),bottom .42s cubic-bezier(.32,.72,0,1),left .34s cubic-bezier(.32,.72,0,1),right .34s cubic-bezier(.32,.72,0,1),border-radius .3s cubic-bezier(.32,.72,0,1)}
:host([data-pos="left"]) .root.gone .row{transform:translateX(calc(-100% - 29px - var(--hk-content-left,0px) - var(--hk-pane-l,0px)))}
:host([data-pos="right"]) .root.gone .row{transform:translateX(calc(100% + 29px + var(--hk-pane-r,0px)))}
:host([data-pos="left"]) .row,:host([data-pos="right"]) .row{transition:transform .34s cubic-bezier(.32,.72,0,1)}
@media (prefers-reduced-motion:reduce){.row,.pill,.roomsbtn,.sheet,.tab.here::before{transition:none}}
:host([data-icons]) .tab span{display:none}
